import re

from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.egate.generictabcontent import GenericTabContent

__author__ = "Adrianna Pienkowska"
__copyright__ = "Copyright (C) 2018, Nokia"
__email__ = "adrianna.pienkowska@nokia.com"


class PgwStats(GenericTabContent):
    """Pgwstats command class."""

    def __init__(self, connection, pgw_id, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Pgwstats command.

        :param connection: moler connection to device, terminal when command is executed.
        :param pgw_id: id of pgw.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(PgwStats, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.pgw_id = pgw_id
        self.options = options
        self.current_ret["DICT"] = {}

        # private variables
        self._current_tuple = None
        self._inter_table = None
        self._headers = []

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "pgw_stats"
        if self.pgw_id:
            cmd = f"{cmd} id={self.pgw_id}"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_not_configured_pgw(line)
                self._parse_current_device_info(line)
                self._parse_internal_table(line)
                self._parse_data_row(line)
                self._parse_headers(line)
                self._parse_vertical_table(line)
            except ParsingDone:
                pass
        return super(PgwStats, self).on_new_line(line, is_full_line)

    _re_configured = re.compile(r"is not configured")

    def _parse_not_configured_pgw(self, line):
        if self._regex_helper.search_compiled(PgwStats._re_configured, line):
            self.set_exception(CommandFailure(self, f"Error: {line}"))
            raise ParsingDone

    _re_device_info = re.compile(r"(?P<DEVICE>PGW-\d+),\s+data_iface=(?P<IFACE>.*);\sdir=(?P<DIR>.*);")

    def _parse_current_device_info(self, line):
        if self._regex_helper.search_compiled(PgwStats._re_device_info, line):
            device = self._regex_helper.group("DEVICE")
            data_iface = self._regex_helper.group("IFACE")
            direction = self._regex_helper.group("DIR")
            device_tuple = (device, data_iface, direction)
            self._current_tuple = device_tuple
            self._check_if_in_dict()
            self._inter_table = None
            self._headers = []
            raise ParsingDone

    def _parse_internal_table(self, line):
        matched = re.split(r"\s{2,}", line)
        if matched[0] == "" and len(matched) == 2:
            self._inter_table = matched[1]
            raise ParsingDone

    def _parse_data_row(self, line):
        matched = re.split(r"\s{2,}", line)
        if len(matched) == 2 and matched[0] != "" and matched[0] != "Parameter":
            split = matched[1].split()
            matched[1] = int(split[0])
            row_dict = {matched[0]: matched[1]}
            self._parse_to_inter_table(row_dict)
            raise ParsingDone

    def _check_if_in_dict(self):
        if self._current_tuple:
            (device, data_if, direct) = self._current_tuple
            if device in self.current_ret["DICT"]:
                if data_if in self.current_ret["DICT"][device]:
                    if direct in self.current_ret["DICT"][device][data_if]:
                        pass
                    else:
                        self.current_ret["DICT"][device][data_if].update({direct: {}})
                else:
                    self.current_ret["DICT"][device].update({data_if: {}})
                    self.current_ret["DICT"][device][data_if].update({direct: {}})
            else:
                self.current_ret["DICT"].update({device: {}})
                self.current_ret["DICT"][device].update({data_if: {}})
                self.current_ret["DICT"][device][data_if].update({direct: {}})

    def _parse_to_inter_table(self, row_dict):
        (device, data_if, direct) = self._current_tuple
        if self._inter_table:
            if self._inter_table in self.current_ret["DICT"][device][data_if][direct]:
                self.current_ret["DICT"][device][data_if][direct][self._inter_table].update(row_dict)
            else:
                self.current_ret["DICT"][device][data_if][direct].update({self._inter_table: row_dict})
        else:
            self.current_ret["DICT"][device][data_if][direct].update(row_dict)

    def _parse_headers(self, line):
        matched = re.split(r"\s{2,}", line)
        if len(matched) > 4 and not self._headers:
            self._headers = matched
            raise ParsingDone

    def _parse_vertical_table(self, line):
        matched = re.split(r"\s{2,}", line)
        if len(matched) > 4 and self._headers:
            matched = [int(item) for item in matched if item]
            row_dict = dict(zip(self._headers, matched))
            (device, data_if, direct) = self._current_tuple
            self.current_ret["DICT"][device][data_if][direct].update({"DATA": row_dict})


